/**
 * Shader for the ribbons.
 *
 * ## The mathematical idea
 *
 * Each ribbon is a horizontal sinusoid with its own phase, and its light is an
 * exponential of the vertical distance to its axis: far from the ribbon the
 * contribution fades out, close to it it saturates gently. The ribbons sum
 * together, so that their crossings brighten by themselves.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB`, `uColorC` — the two hues between which the ribbons are staged,
 *   from the bottom up.
 * - `uSpeed` — speed of the undulation.
 * - `uCount` — number of ribbons, bounded at ten.
 * - `uAmplitude` — height of the undulation, as a fraction of the frame.
 */
export const RIBBONS_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uCount;
uniform float uAmplitude;

// Three sines at non-multiple frequencies: they never fall back into phase,
// so the undulation does not read as a mechanical pattern.
float ribbonWave(float x, float phase) {
  return sin(x * 1.0 + phase) * 0.55
    + sin(x * 2.1 + phase * 1.7) * 0.30
    + sin(x * 3.7 + phase * 0.6) * 0.15;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float x = vUv.x * aspect * 4.0;
  float t = uTime * uSpeed;

  float ribbons = clamp(uCount, 1.0, 10.0);
  vec3 colour = uColorA;

  for (int i = 0; i < 10; i += 1) {
    if (float(i) >= ribbons) break;

    float k = (float(i) + 0.5) / ribbons;

    // The vertical phase offset: each ribbon gets a phase tied to its rank,
    // without which they would all undulate as a single block.
    float axis = k + uAmplitude * ribbonWave(x, t + k * 6.28318);

    // Attenuation by distance to the axis: an exponential, the profile of a
    // glow, where a plain threshold would make flat bands.
    float offset = abs(vUv.y - axis);
    float glow = exp(-offset * offset * 2400.0) + exp(-offset * offset * 220.0) * 0.35;

    vec3 tint = mix(uColorB, uColorC, k);
    colour += tint * glow * (0.35 + 0.65 * k);
  }

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Ribbons: staged sinusoidal bands, undulating as they cross.
 *
 * ## The principle
 *
 * Each ribbon is a sinusoid with its own phase; its light is an exponential of the vertical distance to its axis.
 *
 * The ribbons sum together: their crossings brighten by themselves, with no test at all.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its fallback.
 * Reading the tokens, converting them to floats and re-reading them when the
 * theme changes all come from the engine — copying that here would leave as many
 * versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one per
 * backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { RIBBONS_FRAGMENT } from './ribbons.shader.js'

/** What the escape hatch receives. */
export interface RibbonsControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface RibbonsOwnProps {
  /** Speed of the undulation. @defaultValue 0.4 */
  speed?: number
  /** Number of ribbons. @defaultValue 5 */
  count?: number
  /** Height of the undulation, as a fraction of the frame. @defaultValue 0.08 */
  amplitude?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<RibbonsControls>
}

/** All props. */
export type RibbonsProps = Customisable<RibbonsOwnProps>

/** Tokens used by default: the background, then the two hues of the ribbons. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-teal-400',
  '--o-palette-sky-300',
] as const

/** Default fallback: a frozen gradient, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-b o-from-zinc-50 dark:o-from-zinc-950 o-to-zinc-50 dark:o-to-sky-950'

/**
 * Ribbons.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Ribbons className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Ribbons({
  speed = 0.4,
  count = 5,
  amplitude = 0.08,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: RibbonsProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: RIBBONS_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uCount: count, uAmplitude: amplitude },
    name: 'ribbons',
    // Each ribbon adds three sines and two exponentials per fragment: it is
    // the setting that weighs, so it is the one that is bounded.
    degrade: (quality) => ({
      uCount: quality === 'low' ? Math.min(count, 4) : count,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
